-- Only promote untouched non-art drafts. Art records and editor changes are protected.
begin;
create temporary table kk_art_changed(id uuid primary key) on commit drop;
with changed as (
 insert into public.kk_museums as m(id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum)
 select id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum from jsonb_populate_recordset(null::public.kk_museums,'[{"id":"08c3d4c2-0fb4-5732-8916-5eda0748d06d","inventory_key":"art-audit:160","name":"Koppelkerk - vrijplaats voor kunst & cultuur","city":"Bredevoort","province":"Gelderland","street_address":"Koppelstraat 35","postal_code":"7126 AG","country":"NL","website_url":"https://koppelkerk.nl/","latitude":null,"longitude":null,"summary":"Ontdek wisselende beeldende kunst in een voormalige kerk. De Koppelkerk verbindt tentoonstellingen met lezingen en andere culturele ontmoetingen. De rustige ruimte geeft gelegenheid om te kijken, na te denken en na te praten.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["kunsthal","hedendaagse kunst"],"photos":[{"url":"https://upload.wikimedia.org/wikipedia/commons/4/41/Koppelkerk_Bredevoort.jpeg","caption":"Koppelkerk - vrijplaats voor kunst & cultuur — Koppelkerk Bredevoort","credit":"ErikKoppelkerk","source_url":"https://commons.wikimedia.org/wiki/File:Koppelkerk_Bredevoort.jpeg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"35e5e40b-4f64-55b3-b8ca-de87aa30f31a","inventory_key":"museum-nl:royal-delft-museum","name":"Royal Delft","city":"Delft","province":"Zuid-Holland","street_address":"Rotterdamseweg 196","postal_code":"2628 AR","country":"NL","website_url":"https://www.royaldelft.com/","latitude":52.001268,"longitude":4.367013,"summary":"Ontdek de wereld achter het blauw. Royal Delft verbindt beschilderd aardewerk met het ambacht waarmee het wordt gemaakt. Historische collecties en het werk van makers laten zien hoe traditie telkens opnieuw vorm krijgt.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["keramiek","Delfts blauw","toegepaste kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Royal_Delft_2024-12-02.jpg/1280px-Royal_Delft_2024-12-02.jpg","caption":"Royal Delft — Royal Delft 2024-12-02","credit":"Andy Li","source_url":"https://commons.wikimedia.org/wiki/File:Royal_Delft_2024-12-02.jpg","license":"CC0"}],"is_art_museum":true},{"id":"65d8b256-8a18-539d-9108-e66ce17e8758","inventory_key":"museum-nl:west-den-haag","name":"West Den Haag","city":"Den Haag","province":"Zuid-Holland","street_address":"Lange Voorhout 102","postal_code":"2514 EJ","country":"NL","website_url":"https://www.westdenhaag.nl/","latitude":null,"longitude":null,"summary":"Ontdek actuele kunst bij West Den Haag. Wisselende tentoonstellingen, onderzoek en ontmoetingen geven ruimte aan kunstenaars met uiteenlopende ideeën. Het programma nodigt je uit om vertrouwde beelden en gewoonten opnieuw te bekijken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal","experiment"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/West_Den_Haag_former_American_embassy_%2851625772599%29.jpg/1280px-West_Den_Haag_former_American_embassy_%2851625772599%29.jpg","caption":"West Den Haag — West Den Haag former American embassy (51625772599)","credit":"Sandra Fauconnier","source_url":"https://commons.wikimedia.org/wiki/File:West_Den_Haag_former_American_embassy_(51625772599).jpg","license":"CC BY 2.0"}],"is_art_museum":true},{"id":"97f2055d-0eef-523b-8d30-023c82c8dd49","inventory_key":"museum-nl:het-mow-museum-westerwolde","name":"MOW I Museum Westerwolde","city":"Bellingwolde","province":"Groningen","street_address":"Hoofdweg 161","postal_code":"9695 AE","country":"NL","website_url":"https://www.hetmow.nl","latitude":53.113054,"longitude":7.161994,"summary":"Kijk met andere ogen naar de regio bij MOW. Wisselende kunsttentoonstellingen vertrekken vanuit vragen en verhalen dichtbij huis. Kunstenaars verbinden het landschap en het dagelijks leven met onderwerpen die verder reiken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","landschap","kunsthal"],"photos":[{"url":"https://upload.wikimedia.org/wikipedia/commons/8/8b/Museum_de_Oude_Wolden_3.jpg","caption":"MOW I Museum Westerwolde — Museum de Oude Wolden 3","credit":"Editør","source_url":"https://commons.wikimedia.org/wiki/File:Museum_de_Oude_Wolden_3.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"8edfa3a7-938a-5511-92d1-8c4914560b37","inventory_key":"museum-nl:zandvoorts-museum","name":"Zandvoorts Museum","city":"Zandvoort","province":"Noord-Holland","street_address":"Swalu 1","postal_code":"2042 KA","country":"NL","website_url":"https://www.zandvoortsmuseum.nl/","latitude":52.372538,"longitude":4.531619,"summary":"Ontdek de artistieke kant van Zandvoort. Schilderijen en wisselende tentoonstellingen laten zien hoe kunstenaars de kust en het leven verbeelden. De kunstcollectie staat naast voorwerpen die het verhaal van de badplaats vertellen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["schilderkunst","moderne kunst"],"photos":[{"url":"https://upload.wikimedia.org/wikipedia/commons/5/54/Zandvoortmuseum.jpg","caption":"Zandvoorts Museum — Zandvoortmuseum","credit":"Alwin Nagel","source_url":"https://commons.wikimedia.org/wiki/File:Zandvoortmuseum.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"7068c110-e6b8-540b-8d36-b3f19c14cd58","inventory_key":"museum-nl:stadsmuseum-woerden","name":"Stadsmuseum Woerden","city":"Woerden","province":"Utrecht","street_address":"Kerkplein 6","postal_code":"3441 BG","country":"NL","website_url":"https://www.stadsmuseumwoerden.nl/","latitude":52.086119,"longitude":4.88455,"summary":"Ontdek het Groene Hart door de ogen van schilders. Landschappen en werk van Woerdense kunstenaars, waaronder Leo Gestel, geven het stadsmuseum een uitgesproken kunstkant. De historische zalen vormen