"source_url":"https://commons.wikimedia.org/wiki/File:Museum_De_Buitenplaats_-_overzicht_gebouw.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"1f036ced-beb0-5d00-9813-540bc690d4b6","inventory_key":"museum-nl:mondriaanhuis","name":"Mondriaanhuis","city":"Amersfoort","province":"Utrecht","street_address":"Kortegracht 11","postal_code":"3811 KG","country":"NL","website_url":"https://www.mondriaanhuis.nl/nl","latitude":52.154748,"longitude":5.39038,"summary":"Volg Mondriaans weg van landschap naar abstractie in zijn geboortehuis. Presentaties en een reconstructie van zijn Parijse atelier laten zijn zoektocht zien. Kleur, ritme en ruimte maken duidelijk hoe radicaal zijn blik veranderde.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["kunstenaarsmuseum","De Stijl","Piet Mondriaan"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/Amersfoort_Mondriaanhuis_seen_from_the_north.jpg/1280px-Amersfoort_Mondriaanhuis_seen_from_the_north.jpg","caption":"Mondriaanhuis — Amersfoort Mondriaanhuis seen from the north","credit":"Ymblanter","source_url":"https://commons.wikimedia.org/wiki/File:Amersfoort_Mondriaanhuis_seen_from_the_north.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"819d6419-6798-5c8f-97ad-d9885053aa3c","inventory_key":"museum-nl:kunsthal-kade","name":"Kunsthal KAdE","city":"Amersfoort","province":"Utrecht","street_address":"Eemplein 77","postal_code":"3812 EA","country":"NL","website_url":"https://www.kunsthalkade.nl/nl","latitude":52.159009,"longitude":5.382722,"summary":"Ontdek telkens een andere wereld bij Kunsthal KAdE. Zonder vaste collectie kan de kunsthal uiteenlopende kunstenaars, beeldculturen en ontwerpvragen onderzoeken. De wisselende tentoonstellingen geven ruimte aan zowel verwondering als verdieping.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["kunsthal","hedendaagse kunst","design"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/20140513Eemhuis43rx.JPG/1280px-20140513Eemhuis43rx.JPG","caption":"Kunsthal KAdE — 20140513Eemhuis43rx","credit":"user:WeeJeeVee","source_url":"https://commons.wikimedia.org/wiki/File:20140513Eemhuis43rx.JPG","license":"CC BY-SA 3.0 nl"}],"is_art_museum":true},{"id":"4b4a010e-6083-5758-b0d6-4f3f2e30d155","inventory_key":"museum-nl:elleboogkerk","name":"Elleboogkerk","city":"Amersfoort","province":"Utrecht","street_address":"Langegracht 36","postal_code":"3811 BW","country":"NL","website_url":"https://www.elleboogkerk.nl/","latitude":52.157331,"longitude":5.387037,"summary":"Ervaar ruimtelijke kunst in de hoge Elleboogkerk. Grote installaties krijgen hier de ruimte om hun eigen omgeving te maken. De tentoonstellingen veranderen, waardoor ook de manier waarop je het gebouw beleeft telkens verschuift.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","installaties","kunsthal"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Amersfoort_Elleboogkerk_1.JPG/1280px-Amersfoort_Elleboogkerk_1.JPG","caption":"Elleboogkerk — Amersfoort Elleboogkerk 1","credit":"Torsade de Pointes","source_url":"https://commons.wikimedia.org/wiki/File:Amersfoort_Elleboogkerk_1.JPG","license":"CC0"}],"is_art_museum":true},{"id":"d4e52858-c159-598c-8acd-9a925ccbf031","inventory_key":"museum-nl:museum-paul-tetar-van-elven","name":"Museum Paul Tetar van Elven","city":"Delft","province":"Zuid-Holland","street_address":"Koornmarkt 67","postal_code":"2611 EC","country":"NL","website_url":"https://tetar.nl/","latitude":52.009523,"longitude":4.358782,"summary":"Stap binnen in het huis van schilder en verzamelaar Paul Tetar van Elven. Zijn werk, historische meubels en porselein maken de negentiende-eeuwse smaak voelbaar. Een persoonlijke verzameling waarin wonen en kunst nauw verweven zijn.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["schilderkunst","kunstenaarsmuseum","toegepaste kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Museum_elven_delft.jpg/1280px-Museum_elven_delft.jpg","caption":"Museum Paul Tetar van Elven — Museum elven delft","credit":"M.Minderhoud","source_url":"https://commons.wikimedia.org/wiki/File:Museum_elven_delft.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"ae8b491e-3964-5b9f-8909-925c3fc93952","inventory_key":"museum-nl:marres-huis-voor-hedendaagse-cultuur","name":"Marres, Huis voor Hedendaagse Cultuur","city":"Maastricht","province":"Limburg","street_address":"Capucijnenstraat 98","postal_code":"6211 RT","country":"NL","website_url":"https://www.marres.org/","latitude":50.851893,"longitude":5.685843,"summary":"Laat je zintuigen meedoen bij Marres. Kunstenaars, performers en andere makers ontwikkelen er presentaties die verder gaan dan kijken alleen. Het historische huis wordt telkens opnieuw een omgeving voor hedendaagse verbeelding.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","installaties","performance"],"photos":[{"url":"https://upload.wikimedia.org/wikipedia/commons/b/be/Marres%2C_Huis_voor_Hedendaagse_Cultuur.jpg","caption":"Marres, Huis voor Hedendaagse Cultuur — Marres, Huis voor Hedendaagse Cultuur","credit":"Marres, Huis voor Hedendaagse Cultuur","source_url":"https://commons.wikimedia.org/wiki/File:Marres,_Huis_voor_Hedendaagse_Cultuur.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"5d25fb1e-5e88-59dd-b988-b570633bbceb","inventory_key":"art-audit:187","name":"BAK Basecamp","city":"Utrecht","province":"Utrecht","street_address":"Pauwstraat 13A","postal_code":"3512 TG","country":"NL","website_url":"https://www.bakonline.org/","latitude":null,"longitude":null,"summary":"Onderzoek samen met kunstenaars hoe kunst zich verhoudt tot de wereld. BAK verbindt artistieke praktijken met maatschappelijke vragen, gesprekken en publicaties. Het programma wisselt; bekijk vooraf welke publieke activiteit er plaatsvindt.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","experiment","maatschappij"],"photos":[],"is_art_museum":true},{"id":"b241837c-03ee-5ad3-a7d2-f89f8f611f92","inventory_key":"museum-nl:museum-w","name":"Museum W","city":"Weert","province":"Limburg","street_address":"Meikoel 2","postal_code":"6001 EE","country":"NL","website_url":"https://www.museumw.nl","latitude":51.25354,"longitude":5.706395,"summary":"Ontdek hoe kunst en historische voorwerpen grote levensvragen raken. Museum W verbindt verschillende tijden en achtergronden in een persoonlijke route. Oude en nieuwe beelden nodigen je uit om je eigen ervaringen mee te nemen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","religieuze kunst","toegepaste kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/Markt_7%2C_Weert_%282%29.jpg/1280px-Markt_7%2C_Weert_%282%29.jpg","caption":"Museum W — Markt 7, Weert (2)","credit":"Rosemoon","source_url":"https://commons.wikimedia.org/wiki/File:Markt_7,_Weert_(2).jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"ebd4b76e-fd97-5fa3-9bbf-1706d111f69a","inventory_key":"museum-nl:museum-klooster-ter-apel","name":"Klooster Ter Apel","city":"Ter Apel","province":"Groningen","street_address":"Boslaan 3-5","postal_code":"9561 LH","country":"NL","website_url":"https://www.kloosterterapel.nl/nl/","latitude":52.876043,"longitude":7.075163,"summary":"Ontdek kunst in de stilte van een voormalig klooster. Religieuze werken vertellen over eeuwen beeldtraditie, terwijl tentoonstellingen hedendaagse kunstenaars ruimte geven. De ontmoeting tussen gebouw en kunst maakt dit een bijzondere plek.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["religieuze kunst","hedendaagse kunst"],"photos":[{"url":"https://upload.wikimedia.org/wikipedia/commons/3/3a/Klooster_Ter_Apel%284%29.jpg","caption":"Klooster Ter Apel — Klooster Ter Apel(4)","credit":"Gouwenaar at Dutch Wikipedia","source_url":"https://commons.wikimedia.org/wiki/File:Klooster_Ter_Apel(4).jpg","license":"Public domain"}],"is_art_museum":true},{"id":"513e04e1-f0c6-50d3-be8b-de4cd63e1d44","inventory_key":"wikipedia:Gelderland:ateliermuseummarishuis:heumen","name":"Ateliermuseum Jac Maris","city":"Heumen","province":"Gelderland","street_address":"Looistraat 57","postal_code":"6582 BB","country":"NL","website_url":"https://www.marishuis.nl/","latitude":null,"longitude":null,"summary":"Bezoek het atelier van Jac Maris en ontdek zijn beelden, keramiek en tekeningen. Verschillende materialen laten zijn veelzijdigheid zien. De beeldentuin verbindt het werk van de kunstenaar met de omgeving waarin hij werkte.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["beeldhouwkunst","keramiek","kunstenaarsmuseum"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/House_Jac_Maris_Heumen_-_1.jpg/1280px-House_Jac_Maris_Heumen_-_1.jpg","caption":"Ateliermuseum Jac Maris — House Jac Maris Heumen - 1","credit":"Hay Kranen","source_url":"https://commons.wikimedia.org/wiki/File:House_Jac_Maris_Heumen_-_1.jpg","license":"CC BY 4.0"}],"is_art_museum":true},{"id":"01454eb6-db10-51bc-b474-c723ff2fc672","inventory_key":"wikipedia:Noord-Brabant:tonsmitshuis:eindhoven","name":"Museum Ton Smits Huis","city":"Eindhoven","province":"Noord-Brabant","street_address":"Jacob Reviuslaan 25","postal_code":"5644 TP","country":"NL","website_url":"https://tonsmitshuis.nl/","latitude":null,"longitude":null,"summary":"Ontdek de humor en verbeelding van Ton Smits in zijn voormalige atelierwoning. Cartoons en schilderijen tonen verschillende kanten van zijn kunstenaarschap. Wisselende presentaties brengen ook andere tekenaars in beeld.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["cartoons","schilderkunst","kunstenaarsmuseum"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/Ton_Smitshuis_Eindhoven.JPG/1280px-Ton_Smitshuis_Eindhoven.JPG","caption":"Museum Ton Smits Huis — Ton Smitshuis Eindhoven","credit":"Rosemoon","source_url":"https://commons.wikimedia.org/wiki/File:Ton_Smitshuis_Eindhoven.JPG","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"6e87864c-3cbf-5a12-9abf-05f60ffa8071","inventory_key":"museum-nl:bureau-europa","name":"Bureau Europa","city":"Maastricht","province":"Limburg","street_address":"Boschstraat 9","postal_code":"6211 AS","country":"NL","website_url":"https://www.bureau-europa.nl/nl/","latitude":50.856762,"longitude":5.690277,"summary":"Kijk opnieuw naar de ontworpen wereld. Bureau Europa presenteert tentoonstellingen over architectuur en vormgeving, met aandacht voor maatschappelijke vragen. Ideeën over ruimte en samenleving worden hier tastbaar en bespreekbaar.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["architectuur","design","kunsthal"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/2019_Maastricht-Timmerfabriek%2C_Bureau_Europa%2C_Stucco_Storico_%28007%29.jpg/1280px-2019_Maastricht-Timmerfabriek%2C_Bureau_Europa%2C_Stucco_Storico_%28007%29.jpg","caption":"Bureau Europa — 2019 Maastricht-Timmerfabriek, Bureau Europa, Stucco Storico (007)","credit":"Kleon3","source_url":"https://commons.wikimedia.org/wiki/File:2019_Maastricht-Timmerfabriek,_Bureau_Europa,_Stucco_Storico_(007).jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"832eabc1-48a4-5297-a18c-cec6be605720","inventory_key":"art-audit:195","name":"R.S.O.L. Art Space","city":"Deventer","province":"Overijssel","street_address":"Ossenweerdstraat 6","postal_code":"7412 BH","country":"NL","website_url":"https://www.tonkruse.nl/rsol.html","latitude":null,"longitude":null,"summary":"Ontdek hedendaagse kunst op kleine schaal bij R.S.O.L. Nieuwe werken en gerichte presentaties brengen actuele artistieke vragen dichtbij. De intieme opzet nodigt uit om aandachtig te kijken en verder te denken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["hedendaagse kunst","kunsthal"],"photos":[],"is_art_museum":true}]'::jsonb)
 on conflict(id) do update set inventory_key=excluded.inventory_key,name=excluded.name,city=excluded.city,province=excluded.province,street_address=excluded.street_address,postal_code=excluded.postal_code,country=excluded.country,website_url=excluded.website_url,latitude=excluded.latitude,longitude=excluded.longitude,summary=excluded.summary,operating_status=excluded.operating_status,publication_status=excluded.publication_status,verification_status=excluded.verification_status,tags=excluded.tags,photos=excluded.photos,is_art_museum=excluded.is_art_museum
 where not m.is_art_museum and m.publication_status='draft'
 and not exists(select 1 from kunstkiezer_private.museum_changes c where c.museum_id=m.id and c.editor_id is not null)
 returning id
) insert into kk_art_changed select id from changed;
